mapper.select:
SELECT * FROM TBL_NOTIFICATION
 WHERE RECEIVER_TYPE = '02' AND CREATED_AT >= TRUNC(SYSDATE) - #{days}
 ORDER BY CREATED_AT DESC, NOTIFICATION_ID DESC

SELECT * FROM TBL_NOTIFICATION
 WHERE RECEIVER_TYPE = '01' AND MEMBER_ID = #{memberId}
 ORDER BY CREATED_AT DESC, NOTIFICATION_ID DESC
